const state={topic:'all',type:'all',lang:'zh'};let items=[];const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function t(zh,en){return state.lang==='zh'?zh:en}
function render(){const filtered=items.filter(n=>(state.topic==='all'||n.topic===state.topic)&&(state.type==='all'||n.type===state.type));$('#count').textContent=filtered.length;$('#officialCount').textContent=filtered.filter(n=>n.type==='official').length;$('#sourceCount').textContent=new Set(filtered.map(n=>n.source)).size;$('#newsGrid').innerHTML=filtered.map(n=>`<article class="card"><div class="card-top"><span class="badge ${n.type}">${n.type==='official'?t('官方公告','OFFICIAL'):n.type==='media'?t('媒体报道','MEDIA'):t('评论 / 分析','COMMENTARY')}</span><time class="date">${n.date}</time></div><h2>${t(n.title_zh,n.title_en)}</h2><p>${t(n.summary_zh,n.summary_en)}</p><div class="card-foot"><span class="source">${n.source} · ${n.topic==='midnight'?'NIGHT':'ADA'}</span><a class="read" href="${n.url}" target="_blank" rel="noopener">${t('阅读原文 ↗','READ ↗')}</a></div></article>`).join('');$('#empty').hidden=filtered.length!==0;$('#stamp').textContent=items.meta?.updated_at||'—';$('#updatedAt').textContent=t('快照 '+(items.meta?.updated_at||''),'SNAPSHOT '+(items.meta?.updated_at||''));$('#heroTitle').textContent=t('看懂生态，分清事实。','Understand the ecosystem.');$('#heroCopy').textContent=t('聚合 Cardano（ADA）与 Midnight（NIGHT）新闻。官方公告、媒体报道、社区评论分层呈现；保留原文来源与时间，不把传闻包装成事实。','Bilingual coverage of Cardano (ADA) and Midnight (NIGHT). Official announcements, media reports and commentary stay separate; sources and publication times remain visible.');$('#trustText').textContent=t('NIGHT 搜索已绑定 Midnight，过滤普通英文词误收。','NIGHT search is bound to Midnight to filter false positives from the common English word.');}
function bind(){$$('.tab').forEach(b=>b.onclick=()=>{$$('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.topic=b.dataset.topic;render()});$$('.filter').forEach(b=>b.onclick=()=>{$$('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.type=b.dataset.type;render()});$('#langBtn').onclick=()=>{state.lang=state.lang==='zh'?'en':'zh';$('#langBtn').textContent=state.lang==='zh'?'EN':'中文';render()};$('#themeBtn').onclick=()=>{document.body.classList.toggle('night-focus');$('#themeBtn').textContent=document.body.classList.contains('night-focus')?'◒ ADA':'☾ NIGHT'}}
fetch('data/news.json').then(r=>r.json()).then(d=>{items=d.items;items.meta=d.meta;bind();render()}).catch(()=>{$('#newsGrid').innerHTML='<div class="empty">暂时无法加载新闻快照。<br><span>Snapshot unavailable.</span></div>'});
